selector_to_html = {"a[href=\"#environment-variable\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment Variable<a class=\"headerlink\" href=\"#environment-variable\" title=\"Link to this heading\">#</a></h2><p>Set a default browser session name via environment variable:</p>", "a[href=\"#attach-via-browser-extension\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Attach via browser extension<a class=\"headerlink\" href=\"#attach-via-browser-extension\" title=\"Link to this heading\">#</a></h3><p>Connect to a browser with the Playwright extension installed:</p>", "a[href=\"#attaching-to-a-running-browser\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attaching to a Running Browser<a class=\"headerlink\" href=\"#attaching-to-a-running-browser\" title=\"Link to this heading\">#</a></h2><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">attach</span></code> to connect to a browser that is already running, instead of launching a new one.</p>", "a[href=\"#named-browser-sessions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Named Browser Sessions<a class=\"headerlink\" href=\"#named-browser-sessions\" title=\"Link to this heading\">#</a></h2><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">-s</span></code> flag to isolate browser contexts:</p>", "a[href=\"#always-clean-up\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2. Always Clean Up<a class=\"headerlink\" href=\"#always-clean-up\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#attach-via-cdp-endpoint\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Attach via CDP endpoint<a class=\"headerlink\" href=\"#attach-via-cdp-endpoint\" title=\"Link to this heading\">#</a></h3><p>Connect to a browser that exposes a Chrome DevTools Protocol endpoint:</p>", "a[href=\"#delete-stale-browser-data\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3. Delete Stale Browser Data<a class=\"headerlink\" href=\"#delete-stale-browser-data\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#attach-by-channel-name\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Attach by channel name<a class=\"headerlink\" href=\"#attach-by-channel-name\" title=\"Link to this heading\">#</a></h3><p>Connect to a running Chrome or Edge instance by its channel name. The browser must have remote debugging enabled \u2014 navigate to <code class=\"docutils literal notranslate\"><span class=\"pre\">chrome://inspect/#remote-debugging</span></code> in the target browser and check \u201cAllow remote debugging for this browser instance\u201d.</p>", "a[href=\"#common-patterns\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Common Patterns<a class=\"headerlink\" href=\"#common-patterns\" title=\"Link to this heading\">#</a></h2><h3>Concurrent Scraping<a class=\"headerlink\" href=\"#concurrent-scraping\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#persistent-profile\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Persistent Profile<a class=\"headerlink\" href=\"#persistent-profile\" title=\"Link to this heading\">#</a></h3><p>By default, browser profile is kept in memory only. Use <code class=\"docutils literal notranslate\"><span class=\"pre\">--persistent</span></code> flag on <code class=\"docutils literal notranslate\"><span class=\"pre\">open</span></code> to persist the browser profile to disk:</p>", "a[href=\"#a-b-testing-sessions\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">A/B Testing Sessions<a class=\"headerlink\" href=\"#a-b-testing-sessions\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#browser-session-isolation-properties\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Browser Session Isolation Properties<a class=\"headerlink\" href=\"#browser-session-isolation-properties\" title=\"Link to this heading\">#</a></h2><p>Each browser session has independent:</p>", "a[href=\"#concurrent-scraping\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Concurrent Scraping<a class=\"headerlink\" href=\"#concurrent-scraping\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#name-browser-sessions-semantically\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1. Name Browser Sessions Semantically<a class=\"headerlink\" href=\"#name-browser-sessions-semantically\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#browser-session-commands\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Browser Session Commands<a class=\"headerlink\" href=\"#browser-session-commands\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#default-browser-session\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Default Browser Session<a class=\"headerlink\" href=\"#default-browser-session\" title=\"Link to this heading\">#</a></h2><p>When <code class=\"docutils literal notranslate\"><span class=\"pre\">-s</span></code> is omitted, commands use the default browser session:</p>", "a[href=\"#browser-session-management\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Browser Session Management<a class=\"headerlink\" href=\"#browser-session-management\" title=\"Link to this heading\">#</a></h1><p>Run multiple isolated browser sessions concurrently with state persistence.</p>", "a[href=\"#best-practices\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Best Practices<a class=\"headerlink\" href=\"#best-practices\" title=\"Link to this heading\">#</a></h2><h3>1. Name Browser Sessions Semantically<a class=\"headerlink\" href=\"#name-browser-sessions-semantically\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#detach\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Detach<a class=\"headerlink\" href=\"#detach\" title=\"Link to this heading\">#</a></h3><p>Tear down an attached session without affecting the external browser:</p>", "a[href=\"#browser-session-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Browser Session Configuration<a class=\"headerlink\" href=\"#browser-session-configuration\" title=\"Link to this heading\">#</a></h2><p>Configure a browser session with specific settings when opening:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
